PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "jugadas_boleta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "referencia" varchar(32) NOT NULL UNIQUE, "fecha_sorteo" date NOT NULL, "monto_total" decimal NOT NULL, "premios_total" decimal NOT NULL, "estado" varchar(16) NOT NULL, "cancelada_en" datetime NULL, "motivo_cancelacion" text NOT NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "creado_en" datetime NOT NULL, "actualizado_en" datetime NOT NULL, "cancelada_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "comercial_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "creado_por_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "destinatario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "forma_pago_id" bigint NULL REFERENCES "pagos_formapago" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
COMMIT;
